// ════════════════════════════════════════════════════════════════════════════
// 手帐素材包 · 声明式清单（material-pack/v1）—— PNG 位图素材的目录页 + 元数据
// ────────────────────────────────────────────────────────────────────────────
// 与 journal-stickers（内联 SVG 矢量贴纸）互补：本包收录用户手绘/扫描的位图素材，
// 已抠去背景（透明 PNG）、按形状特征分四类，存放在 public/journal-materials/。
//
// 设计原则（对齐本仓 sticker-pack/v1 与 map-skill/v1 先例）：
// - 声明式、自包含：一份清单 + 一批 PNG 即全部内容，复制即安装。
// - 渐进披露：常驻仅本清单（id/名称/分类/尺寸）→ 用到才取 PNG（见 catalog.ts）。
// - 放置/持久化交给宿主手帐（lib/journal 页元素 type:'sticker' + meta.materialId），
//   本包不自造 store——与 journal-stickers 同一归宿，复用同一元素类型与绘制器。
//
// 本文件只声明「有哪些素材、什么比例」——不含美术二进制、不碰持久化。
// 运行时契约在 catalog.ts；渲染在 JournalMaterials 的 JournalElementView；选择器在 MaterialLibrary。
// ════════════════════════════════════════════════════════════════════════════

export const MATERIAL_PACK_FORMAT = 'material-pack/v1';

/** 素材分类：按组织手帐时的用途分——胶带横贴、票根竖夹、贴纸点缀、装饰补白 */
export type MaterialCategory = 'tape' | 'ticket' | 'sticker' | 'deco';

/** 一枚位图素材的声明式元数据 */
export interface MaterialMeta {
  id: string;            // kebab-case，全包唯一，如 'mat-tape-01'
  category: MaterialCategory;
  name: string;          // 中文展示名
  file: string;          // 文件名（在 public/journal-materials/<category>/ 下）
  w: number;             // 原图宽（px，用于比例与默认尺寸）
  h: number;             // 原图高（px）
}

export interface MaterialCategoryInfo {
  key: MaterialCategory;
  label: string;         // 中文分类名
  emoji: string;         // 分类小图标
  hint: string;          // 用法提示
}

export interface MaterialPackManifest {
  format: typeof MATERIAL_PACK_FORMAT;
  name: string;          // kebab-case 包名
  displayName: string;   // 中文展示名
  description: string;   // 做什么 + 何时用 + 不适用
  version: string;
  author?: string;
  baseDir: string;       // public 下的根目录（运行时拼 path 用）
  categories: MaterialCategoryInfo[];
  materials: MaterialMeta[];
}

